from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class MeasurementInfoPMV1(SchemaObject):
    id = SchemaField(name="id")
    name = SchemaField(name="name")
    abbreviation = SchemaField(name="abbreviation")
    counters = SchemaField(name="counters")

    def __init__(self, id, name, abbreviation, counters):
        self.id = id
        self.name = name
        self.abbreviation = abbreviation
        self.counters = counters
        super(MeasurementInfoPMV1, self).__init__()
